CREATE TABLE IF NOT EXISTS labels (
  id         TEXT    PRIMARY KEY,
  name       TEXT    NOT NULL UNIQUE,
  color      TEXT    NOT NULL DEFAULT '#888888',
  created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS message_labels (
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  label_id   TEXT NOT NULL REFERENCES labels(id)   ON DELETE CASCADE,
  PRIMARY KEY (message_id, label_id)
);

CREATE TABLE IF NOT EXISTS settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TRIGGER IF NOT EXISTS messages_ai AFTER INSERT ON messages BEGIN
  INSERT INTO messages_fts(rowid, subject, from_addr, snippet, text)
  VALUES (new.rowid, new.subject, new.from_addr, new.snippet, new.text);
END;

CREATE TRIGGER IF NOT EXISTS messages_ad AFTER DELETE ON messages BEGIN
  INSERT INTO messages_fts(messages_fts, rowid, subject, from_addr, snippet, text)
  VALUES('delete', old.rowid, old.subject, old.from_addr, old.snippet, old.text);
END;

CREATE TRIGGER IF NOT EXISTS messages_au AFTER UPDATE ON messages BEGIN
  INSERT INTO messages_fts(messages_fts, rowid, subject, from_addr, snippet, text)
  VALUES('delete', old.rowid, old.subject, old.from_addr, old.snippet, old.text);
  INSERT INTO messages_fts(rowid, subject, from_addr, snippet, text)
  VALUES (new.rowid, new.subject, new.from_addr, new.snippet, new.text);
END;

CREATE TABLE IF NOT EXISTS push_subscriptions (
  endpoint   TEXT PRIMARY KEY,
  p256dh     TEXT,
  auth       TEXT,
  created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS config (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS user_settings (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  key     TEXT NOT NULL,
  value   TEXT NOT NULL,
  PRIMARY KEY (user_id, key)
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS login_attempts (
  key          TEXT PRIMARY KEY,
  fails        INTEGER NOT NULL DEFAULT 0,
  window_start INTEGER NOT NULL,
  locked_until INTEGER
);

CREATE TABLE message_labels (
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  label_id   TEXT NOT NULL REFERENCES labels(id)   ON DELETE CASCADE,
  PRIMARY KEY (message_id, label_id)
);

CREATE TRIGGER messages_ai AFTER INSERT ON messages BEGIN
  INSERT INTO messages_fts(rowid, subject, from_addr, snippet, text, user_id)
  VALUES (new.rowid, new.subject, new.from_addr, new.snippet, new.text, new.user_id);
END;

CREATE TRIGGER messages_ad AFTER DELETE ON messages BEGIN
  INSERT INTO messages_fts(messages_fts, rowid, subject, from_addr, snippet, text, user_id)
  VALUES('delete', old.rowid, old.subject, old.from_addr, old.snippet, old.text, old.user_id);
END;

CREATE TRIGGER messages_au AFTER UPDATE ON messages BEGIN
  INSERT INTO messages_fts(messages_fts, rowid, subject, from_addr, snippet, text, user_id)
  VALUES('delete', old.rowid, old.subject, old.from_addr, old.snippet, old.text, old.user_id);
  INSERT INTO messages_fts(rowid, subject, from_addr, snippet, text, user_id)
  VALUES (new.rowid, new.subject, new.from_addr, new.snippet, new.text, new.user_id);
END;
